function queryDecisionLibrary({ country, iso2, threat, limit = 40 } = {}) {
  const c = String(country || "").toLowerCase();
  const i = String(iso2 || "").toLowerCase();
  const t = String(threat || "").toLowerCase();
  return securityDecisionLibrary.filter(row => {
    const countryHit = !c || String(row.country).toLowerCase().includes(c);
    const isoHit = !i || String(row.iso2).toLowerCase() === i;
    const threatHit = !t || String(row.threatType).toLowerCase().includes(t) || String(row.threatDescription).toLowerCase().includes(t);
    return countryHit && isoHit && threatHit;
  }).slice(0, Number(limit) || 40);
}
module.exports = { securityDecisionLibrary, queryDecisionLibrary };
